cd ~/.claude/projects/-home-hyphyphyph-piton-repl; ls -la 48618177*.jsonl | awk '{print $5}'; python3 - <<'E'
import json,collections
L=[json.loads(l) for l in open('48618177-8091-4852-ac29-8cdda121add7.jsonl')]
b=[i for i,e in enumerate(L) if e.get('type')=='system' and 'compact' in (e.get('subtype') or '')]
live=L[b[-1]:] if b else L
tn={}; by=collections.Counter()
for e in live:
    c=(e.get('message') or {}).get('content')
    if isinstance(c,str): by[e.get('type')+':text']+=len(c); continue
    for x in c or []:
        t=x.get('type')
        if t=='tool_use': tn[x['id']]=x['name']; by['tool_use:'+x['name']]+=len(json.dumps(x.get('input')))
        elif t=='tool_result': by['tool_result:'+tn.get(x.get('tool_use_id'),'?')]+=len(json.dumps(x.get('content')))
        elif t=='text': by[e.get('type')+':text']+=len(x.get('text',''))
tot=sum(by.values()); print('compactions',len(b),'live chars',f'{tot:,}')
for k,v in by.most_common(6): print(f'{v/tot*100:5.1f}% {k}')
E

